update packages set price_from = 1647, currency = 'USD', price_type = 'per-person' where id = (select id from nodes where node_type = 'package' and slug = '8-night-maldives-fishing-package-half-day-fishing');
update bookable_products set base_price = 1647, currency = 'USD' where id = (select id from nodes where node_type = 'package' and slug = '8-night-maldives-fishing-package-half-day-fishing');
update package_itinerary_stages set description = '8 nights at Maldives Fishing and Holidays Lodge, Maamendhoo, Gaafu Alifu Atoll, with 7 days of half-day reef fishing on a private boat for your group. Full-board meals, twin-share rooms, airport meet and greet, return domestic flight and boat transfer included.' where package_id = (select id from nodes where node_type = 'package' and slug = '8-night-maldives-fishing-package-half-day-fishing') and stage_number = 1;
update package_itinerary_items i set quantity = 7, notes = '7 days of half-day reef fishing — popping, jigging and bottom fishing along the reef edges and channels.', component_node_id = (select id from nodes where node_type = 'activity' and slug = 'private-half-day-fishing-charter') from package_itinerary_stages s where i.stage_id = s.id and s.package_id = (select id from nodes where node_type = 'package' and slug = '8-night-maldives-fishing-package-half-day-fishing') and s.stage_number = 1 and i.component_role = 'activity';
